package signing

import "encoding/hex"

// Code generated from Apple certificate authority chain (zsign embedded certs).
// Contains WWDR G1-G8 intermediates and Apple Root CA / Root CA - G3.

type appleCert struct {
	gen string
	raw []byte
}

var appleChainCerts = []appleCert{
	{"cert0", mustHex("")},
	{"cert1", mustHex("")},
	{"cert2", mustHex("")},
	{"cert3", mustHex("")},
	{"cert4", mustHex("")},
	{"cert5", mustHex("")},
	{"cert6", mustHex("")},
	{"cert7", mustHex("")},
	{"cert8", mustHex("")},
	{"cert9", mustHex("")},
}

func mustHex(s string) []byte {
	b, err := hex.DecodeString(s)
	if err != nil {
		panic(err)
	}
	return b
}
